;/* lot2: autoplay animations when in view */
(function(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
const inView=(el,cb)=>{let on=false;new IntersectionObserver(es=>{on=es[0].isIntersecting;cb(on)},{threshold:.35}).observe(el);return()=>on};
const pulse=(el,onMs,offMs)=>{let t,live=false,hov=false;el.addEventListener('pointerenter',()=>hov=true);el.addEventListener('pointerleave',()=>hov=false);
  const cyc=()=>{if(!live)return;if(!hov){el.classList.add('auto');setTimeout(()=>el.classList.remove('auto'),onMs)}t=setTimeout(cyc,onMs+offMs)};
  inView(el,v=>{live=v;clearTimeout(t);if(v)t=setTimeout(cyc,500);else el.classList.remove('auto')})};
document.querySelectorAll('.labwrap,.epile').forEach(el=>pulse(el,2600,1800));
const T=[...document.querySelectorAll('.terms li')];if(T.length){let i=0,t,live=false;const step=()=>{if(!live)return;T.forEach((x,k)=>x.classList.toggle('auto',k===i));i=(i+1)%T.length;t=setTimeout(step,1700)};
  inView(T[0].closest('section'),v=>{live=v;clearTimeout(t);if(v)step();else T.forEach(x=>x.classList.remove('auto'))})}
const ba=document.getElementById('ba'),r=ba&&ba.querySelector('input[type=range]');if(ba&&r){let live=false,busy=false,touched=0;
  ['pointerdown','input'].forEach(e=>r.addEventListener(e,ev=>{if(ev.isTrusted)touched=performance.now()}));
  const set=v=>{r.value=v;r.dispatchEvent(new Event('input'))};
  const sweep=()=>{if(!live||busy||performance.now()-touched<6000)return;busy=true;const t0=performance.now();(function w(t){const q=(t-t0)/3200;if(q>1){set(50);busy=false;return}set(50+Math.sin(q*Math.PI*2)*38);requestAnimationFrame(w)})(t0)};
  inView(ba,v=>live=v);setInterval(sweep,5500)}
})();
